import sys

steps, arr_len = map(int, sys.stdin.read().split())
MOD = 10**9 + 7
cur = {0: 1}
for _ in range(steps):
    nxt = {}
    for pos, c in cur.items():
        for d in (-1, 0, 1):
            q = pos + d
            if 0 <= q < arr_len:
                nxt[q] = (nxt.get(q, 0) + c) % MOD
    cur = nxt
print(cur.get(0, 0) % MOD)

